   "prompt": "너는 고등학생과 함께 작업하는 친절한 웹 개발자야. 아래 요구사항대로 '도식화 그리기판' 웹앱을 만들어줘.\n\n[만들 것]\n티셔츠·원피스·바지 기본 도식화 틀 위에 선을 그리고 색을 칠해 나만의 옷을 디자인하는 그리기 앱\n\n[사용 대상]\n패션디자인과 고등학생과 패션에 관심 있는 친구들\n\n[핵심 기능]\n1. 상단에서 티셔츠·원피스·바지 3가지 기본 도식화 틀(SVG 선화)을 선택하면 캔버스 배경으로 표시\n2. 마우스와 손가락 터치 모두로 자유롭게 선 그리기(펜 굵기 3단계 선택)\n3. 색상 팔레트 12색 + 직접 색 고르기(color input), 지우개, 전체 지우기, 되돌리기(Undo) 버튼\n4. 완성 그림을 PNG 이미지로 내려받기 버튼\n\n[화면 디자인]\n- 분위기: 패션 브랜드 웹사이트처럼 세련된 미니멀 무드(흰 배경, 검정·베이지 포인트, 넉넉한 여백, 얇은 선)\n- 맨 위에 '도식화 그리기판' 제목과 한 줄 사용법 안내\n- 모든 글자와 버튼은 한국어, 버튼은 크고 누르기 쉽게, 누르면 색이 바뀌는 반응 효과\n- 스마트폰(가로 360px)부터 노트북까지 깨지지 않는 반응형 레이아웃\n\n[기술 조건 - 꼭 지켜줘]\n- HTML, CSS, JavaScript를 하나의 HTML 파일에 모두 넣어 완성하고, 코드를 생략하지 말고 끝까지 작성\n- 외부 이미지 파일, 인터넷 서버와 통신하는 외부 API, API 키, 로그인 기능은 사용하지 말 것(Web Audio처럼 브라우저에 내장된 기능은 사용 가능). 그림은 이모지, CSS 도형, SVG, Canvas로 직접 표현\n- 실제 브랜드 로고·상표, 유명 캐릭터, 연예인 사진은 사용하지 말고 모두 오리지널로 만들 것\n- 예시 데이터를 미리 넣어서 화면을 열자마자 바로 동작하게 할 것\n- 입력이 비었거나 잘못되면 알림창(alert) 대신 화면 안에 친절한 안내 문구 표시\n- 드래그·그리기·스와이프는 마우스와 스마트폰 터치에서 모두 되도록 Pointer Events(pointerdown/move/up)를 사용하고, 해당 영역에 CSS touch-action: none 적용\n- PNG 저장은 화면 그림을 Canvas로 옮긴 뒤 toDataURL()로 만들고 다운로드 링크를 자동 클릭하는 방식으로 구현(SVG는 Image로 불러와 Canvas에 그린 뒤 저장)\n- 저장 기능이 필요하면 localStorage를 쓰되 try-catch로 감싸서, 저장이 안 되는 환경에서도 앱은 정상 동작하게 할 것\n\n[완성 전 스스로 점검]\n코드를 보여주기 전에 모든 버튼과 기능이 실제로 동작하는지, 콘솔 오류가 없는지 점검하고, 마지막에 사용 방법을 3줄로 요약해줘.",
